<?php declare(strict_types=1);
use Kulturhus\Verein\{Finance,Documents,InvoiceApprovals};
function ownBankFeeOriginal(PDO $db,string $actor,string $label,string $amount='1',bool $approve=true):array
{
    ownBankGroupDatabase($db);$key=static fn()=>bin2hex(random_bytes(16));$f=new Finance($db,$actor);$entry=$f->createEntry(['kind'=>'expense','category'=>'general','amount'=>$amount,'description'=>'Own real withheld fee '.$label,'counterparty'=>'Own actual bank','document_date'=>'2026-01-20','due_date'=>'2026-01-20'],$key());$text='Own actually withheld bank fee EUR '.$amount.' '.$label;$text=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],$text);$stream='BT /F1 18 Tf 40 740 Td ('.$text.') Tj ET';$objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>','<< /Length '.strlen($stream)." >>\nstream\n".$stream."\nendstream",'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];$bytes="%PDF-1.4\n";$offsets=[];foreach($objects as$i=>$object){$offsets[]=strlen($bytes);$bytes.=($i+1)." 0 obj\n".$object."\nendobj\n";}$xref=strlen($bytes);$bytes.="xref\n0 6\n0000000000 65535 f \n";foreach($offsets as$offset)$bytes.=sprintf("%010d 00000 n \n",$offset);$bytes.="trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n".$xref."\n%%EOF\n";$document=(new Documents($db,$actor))->upload('own-withheld-fee-original.pdf',$bytes,['title'=>'Own exact original fee '.$label,'kind'=>'invoice','scope'=>'finance','links'=>['entry:'.$entry]],$key());if($approve){$approval=new InvoiceApprovals($db,$actor);$review=$approval->state($entry);$approval->approve($entry,$review['hash'],$review['decision_id'],$key(),true);}return compact('entry','document','bytes');
}
